const { AsyncSessionRegistry } = require('./helpers/testHelpers');

describe('AsyncSessionRegistry Tests', () => {
  let registry;

  beforeEach(() => {
    registry = new AsyncSessionRegistry();
  });

  afterEach(() => {
    registry.clear();
  });

  test('Basic async operations', async () => {
    // Test set and get
    await registry.set('key1', { value: 'test1' });
    const result = await registry.get('key1');

    expect(result).toEqual({ value: 'test1' });
  });

  test('Get non-existent key returns undefined', async () => {
    const result = await registry.get('non-existent');
    expect(result).toBeUndefined();
  });

  test('Delete operation works', async () => {
    await registry.set('key1', { value: 'test1' });
    const deleteResult = await registry.delete('key1');
    const getResult = await registry.get('key1');

    expect(deleteResult).toBe(true);
    expect(getResult).toBeUndefined();
  });

  test('Size operation works', async () => {
    expect(await registry.size()).toBe(0);

    await registry.set('key1', { value: 'test1' });
    await registry.set('key2', { value: 'test2' });

    expect(await registry.size()).toBe(2);
  });

  test('Set returns self for chaining', async () => {
    const result = await registry.set('key1', { value: 'test1' });
    expect(result).toBe(registry);
  });

  test('Synchronous methods for test compatibility', () => {
    registry.storage.set('key1', { value: 'test1' });

    expect(registry.has('key1')).toBe(true);
    expect(registry.has('key2')).toBe(false);

    const entries = Array.from(registry.entries());
    expect(entries).toEqual([['key1', { value: 'test1' }]]);
  });

  test('Clear operation works', async () => {
    await registry.set('key1', { value: 'test1' });
    await registry.set('key2', { value: 'test2' });

    expect(await registry.size()).toBe(2);

    registry.clear();

    expect(await registry.size()).toBe(0);
    expect(await registry.get('key1')).toBeUndefined();
    expect(await registry.get('key2')).toBeUndefined();
  });

  test('getAllSessions method for API compatibility', () => {
    registry.storage.set('session1', { guacdHost: 'host1', guacdPort: 4822 });
    registry.storage.set('session2', { guacdHost: 'host2', guacdPort: 4823 });

    const sessions = registry.getAllSessions();

    expect(sessions).toHaveLength(2);
    expect(sessions).toEqual(expect.arrayContaining([
      expect.objectContaining({
        sessionId: 'session1',
        guacdHost: 'host1',
        guacdPort: 4822
      }),
      expect.objectContaining({
        sessionId: 'session2',
        guacdHost: 'host2',
        guacdPort: 4823
      })
    ]));
  });

  test('Registry works with Map-like interface for backwards compatibility', async () => {
    // Test that it behaves like the original Map but with async operations
    await registry.set('test-key', { data: 'test-value' });

    expect(registry.has('test-key')).toBe(true);
    expect(registry.has('missing-key')).toBe(false);

    const value = await registry.get('test-key');
    expect(value.data).toBe('test-value');

    await registry.delete('test-key');
    expect(registry.has('test-key')).toBe(false);
  });
});

const {
    clientOptions,
    callbacks,
    createClientConnection,
    setupTestEnvironment,
    cleanupClientConnection,
    Crypt,
    ClientConnection,
    generateNewConnectionToken
} = require('../helpers/ClientConnectionTestHelpers');

describe('ClientConnection Error Handling and Edge Cases Tests', () => {
    let mockGuacdServer;
    let clientConnection;
    let mockWebSocket;
    let guacdPort;

    beforeEach(async () => {
        const testEnv = setupTestEnvironment();
        mockGuacdServer = testEnv.mockGuacdServer;
        mockWebSocket = testEnv.mockWebSocket;
        guacdPort = testEnv.guacdPort;
        await mockGuacdServer.start();
    });

    afterEach(async () => {
        cleanupClientConnection(clientConnection);
        await mockGuacdServer.stop();
    });

    describe('Error Handling and Edge Cases', () => {
        test('Malformed token structure handling', (done) => {
            const crypt = new Crypt(clientOptions.crypt.cypher, clientOptions.crypt.key);
            const malformedToken = {
                // Missing connection object
                someOtherField: 'value'
            };
            const encryptedToken = crypt.encrypt(malformedToken);

            clientConnection = new ClientConnection(
                clientOptions,
                1,
                mockWebSocket,
                {token: encryptedToken},
                callbacks
            );

            setTimeout(() => {
                expect(clientConnection.state).toBe(clientConnection.STATE_CLOSED);
                done();
            }, 10);
        });

        test('Missing connection type in token', () => {
            const crypt = new Crypt(clientOptions.crypt.cypher, clientOptions.crypt.key);
            const tokenWithoutType = {
                connection: {
                    // Missing type field
                    settings: {
                        hostname: '192.168.1.100'
                    }
                }
            };

            const encryptedToken = crypt.encrypt(tokenWithoutType);
            clientConnection = new ClientConnection(
                clientOptions,
                1,
                mockWebSocket,
                {token: encryptedToken},
                callbacks
            );

            // Should have undefined connection type
            expect(clientConnection.connectionSelector).toBeUndefined();
            expect(clientConnection.state).toBe(clientConnection.STATE_OPEN);
        });
    });

    describe('Resource Exhaustion Prevention', () => {
        test('Extremely large token is handled', (done) => {
            const crypt = new Crypt(clientOptions.crypt.cypher, clientOptions.crypt.key);
            const largeTokenObject = {
                connection: {
                    type: 'rdp',
                    settings: {
                        hostname: '192.168.1.100',
                        // Add a very large string
                        'large-field': 'x'.repeat(100000) // 100KB of 'x'
                    }
                }
            };

            try {
                const encryptedToken = crypt.encrypt(largeTokenObject);

                clientConnection = new ClientConnection(
                    clientOptions,
                    1,
                    mockWebSocket,
                    {token: encryptedToken},
                    callbacks
                );

                // Should handle large tokens gracefully
                expect(clientConnection.connectionSettings.connection.hostname).toBe('192.168.1.100');
                expect(clientConnection.connectionSettings.connection['large-field']).toBe('x'.repeat(100000));
                done();
            } catch (error) {
                // If encryption fails due to size, that's also acceptable
                expect(error).toBeDefined();
                done();
            }
        });

        test('Very deep nested object in token', () => {
            const crypt = new Crypt(clientOptions.crypt.cypher, clientOptions.crypt.key);

            // Create deeply nested object
            let deepObject = {};
            let current = deepObject;
            for (let i = 0; i < 100; i++) {
                current.nested = {};
                current = current.nested;
            }
            current.value = 'deep';

            const deepTokenObject = {
                connection: {
                    type: 'rdp',
                    settings: {
                        hostname: '192.168.1.100'
                    }
                },
                deepField: deepObject
            };

            const encryptedToken = crypt.encrypt(deepTokenObject);

            clientConnection = new ClientConnection(
                clientOptions,
                1,
                mockWebSocket,
                {token: encryptedToken},
                callbacks
            );

            expect(clientConnection.connectionSettings.connection.hostname).toBe('192.168.1.100');
            expect(clientConnection.connectionSettings.deepField).toBeDefined();
        });
    });

    describe('Callback Error Scenarios', () => {
        test('Callback throwing synchronous error is handled', () => {
            const throwingCallbacks = {
                processConnectionSettings: () => {
                    throw new Error('Synchronous error in callback');
                }
            };

            expect(() => {
                clientConnection = new ClientConnection(
                    clientOptions,
                    1,
                    mockWebSocket,
                    {token: generateNewConnectionToken()},
                    throwingCallbacks
                );
            }).toThrow('Synchronous error in callback');
        });

        test('Callback never calling the callback function', (done) => {
            const hangingCallbacks = {
                processConnectionSettings: () => {
                    // Never call callback - this would hang in real scenario
                    // In tests, we'll just verify the connection doesn't proceed
                }
            };

            clientConnection = new ClientConnection(
                clientOptions,
                1,
                mockWebSocket,
                {token: generateNewConnectionToken()},
                hangingCallbacks
            );

            // Connection should remain in open state but never proceed to ready
            setTimeout(() => {
                expect(clientConnection.state).toBe(clientConnection.STATE_OPEN);
                // Should not have guacdClient yet
                expect(clientConnection.guacdClient).toBeUndefined();
                done();
            }, 50);
        });

        test('Callback modifying settings to invalid state', () => {
            const corruptingCallbacks = {
                processConnectionSettings: (settings, callback) => {
                    // Remove required connection object
                    delete settings.connection;
                    callback(null, settings);
                }
            };

            clientConnection = new ClientConnection(
                clientOptions,
                1,
                mockWebSocket,
                {token: generateNewConnectionToken()},
                corruptingCallbacks
            );

            // Connection should be modified by callback
            expect(clientConnection.connectionSettings.connection).toBeUndefined();
            expect(clientConnection.state).toBe(clientConnection.STATE_OPEN);
        });
    });
});

